import { PlaneGeometry, Group, Mesh } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const aspectRatio = 512 / 320;
  const width = 2.0;
  const height = width / aspectRatio;
  const geometry = new PlaneGeometry(width, height);

  const material = new MeshBasicNodeMaterial({
    color: '#ffffff',
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  const mesh = new Mesh(geometry, material);

  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    tex.wrapS = ctx.THREE.ClampToEdgeWrapping;
    tex.wrapT = ctx.THREE.ClampToEdgeWrapping;
    tex.repeat.set(1, 1);
    tex.offset.set(0, 0);
    material.map = tex;
    material.needsUpdate = true;
  });

  const group = new Group();
  group.add(mesh);
  group.userData = {
    handlers: {},
    cleanup: () => {
      geometry.dispose();
      material.dispose();
      if (material.map) material.map.dispose();
    },
  };

  return group;
}
